import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { AddCar } from "../../services/ApiCar";

export default function CardAddVoiture() {
  const navigate = useNavigate();
  const [newCar, setNewCar] = useState({
    matricule: "",
    model: "",
    marque: "",
    libelle: "",
    prix: "",
    prix_jour: "",
    couleur: "",
    disponible: false,
    voiture_image: null,
  });

  const [errors, setErrors] = useState({});

  const handleChange = (e) => {
    const { name, value } = e.target;
    setNewCar({ ...newCar, [name]: value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    let formErrors = {};

    if (!newCar.matricule.trim()) formErrors.matricule = "Le matricule est requis.";
    if (!newCar.model.trim()) formErrors.model = "Le modèle est requis.";
    if (!newCar.marque.trim()) formErrors.marque = "La marque est requise.";
    if (!newCar.libelle.trim()) formErrors.libelle = "Le libellé est requis.";
    if (!newCar.prix) formErrors.prix = "Le prix est requis.";
    if (!newCar.prix_jour) formErrors.prix_jour = "Le prix par jour est requis.";
    if (!newCar.couleur.trim()) formErrors.couleur = "La couleur est requise.";
    if (!newCar.voiture_image) formErrors.voiture_image = "L'image est requise.";

    if (Object.keys(formErrors).length > 0) {
      setErrors(formErrors);
      return;
    }

    const formData = new FormData();
    for (const key in newCar) {
      formData.append(key, newCar[key]);
    }

    try {
      await AddCar(formData);
      setErrors({});
      // Redirection vers la page CardVoiture après succès
      navigate("/admin/");
    } catch (error) {
      console.log(error);
      alert("Une erreur est survenue lors de l'ajout de la voiture.");
    }
  };

  return (
    <>
      <div className="relative flex flex-col min-w-0 break-words w-full mb-6 shadow-lg rounded-lg bg-blueGray-100 border-0">
        <div className="rounded-t bg-white mb-0 px-6 py-6">
          <div className="text-center flex justify-between">
            <h6 className="text-blueGray-700 text-xl font-bold">Ajouter une nouvelle voiture</h6>
            <button
              className="bg-lightBlue-500 text-white font-bold uppercase text-xs px-4 py-2 rounded shadow hover:shadow-md"
              type="button"
              onClick={() => navigate("/admin/Voiture")}
            >
              Retour à la liste
            </button>
          </div>
        </div>

        <div className="flex-auto px-4 lg:px-10 py-10 pt-0">
          <form onSubmit={handleSubmit}>
            {/* Car Information */}
            <h6 className="text-blueGray-400 text-sm mt-3 mb-6 font-bold uppercase">Informations de la voiture</h6>
            <div className="flex flex-wrap">
              {/* Matricule */}
              <div className="w-full lg:w-6/12 px-4">
                <div className="relative w-full mb-3">
                  <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">Matricule</label>
                  <input
                    type="text"
                    name="matricule"
                    value={newCar.matricule}
                    onChange={handleChange}
                    className={`border-0 px-3 py-3 placeholder-blueGray-300 text-blueGray-600 bg-white rounded text-sm shadow w-full ${errors.matricule ? 'border border-red-500' : ''}`}
                    placeholder="Entrez le matricule"
                  />
                  {errors.matricule && <p className="text-red-500 text-xs italic">{errors.matricule}</p>}
                </div>
              </div>

              {/* Model */}
              <div className="w-full lg:w-6/12 px-4">
                <div className="relative w-full mb-3">
                  <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">Modèle</label>
                  <input
                    type="text"
                    name="model"
                    value={newCar.model}
                    onChange={handleChange}
                    className={`border-0 px-3 py-3 placeholder-blueGray-300 text-blueGray-600 bg-white rounded text-sm shadow w-full ${errors.model ? 'border border-red-500' : ''}`}
                    placeholder="Entrez le modèle"
                  />
                  {errors.model && <p className="text-red-500 text-xs italic">{errors.model}</p>}
                </div>
              </div>

              {/* Marque */}
              <div className="w-full lg:w-6/12 px-4">
                <div className="relative w-full mb-3">
                  <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">Marque</label>
                  <input
                    type="text"
                    name="marque"
                    value={newCar.marque}
                    onChange={handleChange}
                    className={`border-0 px-3 py-3 placeholder-blueGray-300 text-blueGray-600 bg-white rounded text-sm shadow w-full ${errors.marque ? 'border border-red-500' : ''}`}
                    placeholder="Entrez la marque"
                  />
                  {errors.marque && <p className="text-red-500 text-xs italic">{errors.marque}</p>}
                </div>
              </div>

              {/* Libelle */}
              <div className="w-full lg:w-6/12 px-4">
                <div className="relative w-full mb-3">
                  <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">Libellé</label>
                  <input
                    type="text"
                    name="libelle"
                    value={newCar.libelle}
                    onChange={handleChange}
                    className={`border-0 px-3 py-3 placeholder-blueGray-300 text-blueGray-600 bg-white rounded text-sm shadow w-full ${errors.libelle ? 'border border-red-500' : ''}`}
                    placeholder="Entrez le libellé"
                  />
                  {errors.libelle && <p className="text-red-500 text-xs italic">{errors.libelle}</p>}
                </div>
              </div>
            </div>

            {/* Pricing */}
            <hr className="mt-6 border-b-1 border-blueGray-300" />
            <h6 className="text-blueGray-400 text-sm mt-3 mb-6 font-bold uppercase">Tarification</h6>
            <div className="flex flex-wrap">
              {/* Prix */}
              <div className="w-full lg:w-4/12 px-4">
                <div className="relative w-full mb-3">
                  <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">Prix</label>
                  <input
                    type="number"
                    name="prix"
                    value={newCar.prix}
                    onChange={handleChange}
                    className={`border-0 px-3 py-3 text-blueGray-600 bg-white rounded text-sm shadow w-full ${errors.prix ? 'border border-red-500' : ''}`}
                    placeholder="Entrez le prix"
                  />
                  {errors.prix && <p className="text-red-500 text-xs italic">{errors.prix}</p>}
                </div>
              </div>

              {/* Prix par jour */}
              <div className="w-full lg:w-4/12 px-4">
                <div className="relative w-full mb-3">
                  <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">Prix / jour</label>
                  <input
                    type="number"
                    name="prix_jour"
                    value={newCar.prix_jour}
                    onChange={handleChange}
                    className={`border-0 px-3 py-3 text-blueGray-600 bg-white rounded text-sm shadow w-full ${errors.prix_jour ? 'border border-red-500' : ''}`}
                    placeholder="Entrez le prix par jour"
                  />
                  {errors.prix_jour && <p className="text-red-500 text-xs italic">{errors.prix_jour}</p>}
                </div>
              </div>

              {/* Couleur */}
              <div className="w-full lg:w-4/12 px-4">
                <div className="relative w-full mb-3">
                  <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">Couleur</label>
                  <input
                    type="text"
                    name="couleur"
                    value={newCar.couleur}
                    onChange={handleChange}
                    className={`border-0 px-3 py-3 text-blueGray-600 bg-white rounded text-sm shadow w-full ${errors.couleur ? 'border border-red-500' : ''}`}
                    placeholder="Entrez la couleur"
                  />
                  {errors.couleur && <p className="text-red-500 text-xs italic">{errors.couleur}</p>}
                </div>
              </div>
            </div>

            {/* Availability & Image */}
            <hr className="mt-6 border-b-1 border-blueGray-300" />
            <h6 className="text-blueGray-400 text-sm mt-3 mb-6 font-bold uppercase">Disponibilité & Image</h6>
            <div className="flex flex-wrap">
              {/* Disponible */}
              <div className="w-full lg:w-4/12 px-4">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2 flex items-center">
                  <input
                    type="checkbox"
                    name="disponible"
                    checked={newCar.disponible}
                    onChange={(e) => setNewCar({ ...newCar, disponible: e.target.checked })}
                    className="form-checkbox h-5 w-5 text-lightBlue-600 mr-2"
                  />
                  Disponible
                </label>
              </div>

              {/* Image Upload */}
              <div className="w-full lg:w-8/12 px-4">
                <div className="relative w-full mb-3">
                  <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">Image</label>
                  <input
                    type="file"
                    name="voiture_image"
                    onChange={(e) => setNewCar({ ...newCar, voiture_image: e.target.files[0] })}
                    className={`border-0 px-3 py-3 text-blueGray-600 bg-white rounded text-sm shadow w-full ${errors.voiture_image ? 'border border-red-500' : ''}`}
                  />
                  {errors.voiture_image && <p className="text-red-500 text-xs italic">{errors.voiture_image}</p>}
                </div>
              </div>
            </div>

            {/* Submit */}
            <div className="text-center mt-6">
              <button
                type="submit"
                className="bg-lightBlue-500 text-white font-bold uppercase text-xs px-6 py-3 rounded shadow hover:shadow-md"
              >
                Ajouter la voiture
              </button>
            </div>
          </form>
        </div>
      </div>
    </>
  );
}
